import path from 'node:path';
import { test, expect } from './fixtures/app.fixture';
import { apiFetch, apiJson } from './helpers/api';
import { openDatasourceSettings } from './helpers/app-actions';
import { scenarioStep } from './support/demo-captions';

/**
 * Mirrors the Feature "Excel and CSV datasources" (specs/capabilities/datasources/spec.md,
 * R53 to R67). The fixtures are generated by fixtures/make-excel-fixtures.cjs:
 * `sales_2026.xlsx` has a "Region" sheet (a title row above the column names and
 * a total row) and an empty "Notes" sheet; `players.csv` has three rows.
 */
const WORKBOOK = path.join(__dirname, 'fixtures', 'sales_2026.xlsx');
const CSV = path.join(__dirname, 'fixtures', 'players.csv');

test.describe('Feature: Excel and CSV datasources', () => {
  test(
    'Uploads a workbook and a CSV, reviews a sheet and saves the datasource',
    { tag: ['@demo', '@story-1.31.4'] },
    async ({ page }) => {
      const name = `Excel e2e ${Date.now()}`;
      const card = (file: string) =>
        page.locator(`[data-testid="file-card"][data-file="${file}"]`);
      const region = card('sales_2026.xlsx').locator(
        '[data-testid="sheet-row"][data-sheet="Region"]',
      );
      const listed = page
        .locator('[data-testid^="datasource-"]')
        .filter({ hasText: name });

      try {
        await scenarioStep(page, 'Given I am in "Datasource Configuration"', async () => {
          await openDatasourceSettings(page);
        });

        await scenarioStep(
          page,
          'When I click "New datasource", name it, choose the kind "Excel / CSV" and upload a workbook and a CSV file',
          async () => {
            await page.getByRole('button', { name: 'New datasource' }).click();
            await page.getByLabel('Name', { exact: true }).fill(name);
            await page.getByLabel('Kind').selectOption('file');
            await page.getByTestId('file-input').setInputFiles([WORKBOOK, CSV]);
          },
        );

        await scenarioStep(
          page,
          'Then I see both files with their sheets, a total-row warning on "Region" and the "Notes" sheet skipped',
          async () => {
            await expect(card('sales_2026.xlsx')).toBeVisible();
            await expect(card('players.csv')).toBeVisible();
            await expect(region.getByTestId('sheet-warning')).toContainText(
              'Last row looks like a total',
            );
            await expect(
              card('sales_2026.xlsx').locator('[data-sheet="Notes"]'),
            ).toContainText('Skipped');
          },
        );

        await scenarioStep(page, 'When I click "Review" on the "Region" sheet', async () => {
          await region.getByTestId('sheet-review').click();
          await expect(page.getByTestId('sheet-review-dialog')).toBeVisible();
          await expect(page.getByTestId('sheet-review-grid')).toBeVisible();
        });

        await scenarioStep(
          page,
          'And I click row number 2 to make it the header row',
          async () => {
            await page.locator('[data-row="2"] button').click();
            await expect(page.getByTestId('sheet-review-header-row')).toHaveValue('2');
            await expect(page.locator('[data-row="1"]')).toHaveAttribute(
              'data-excluded',
              'true',
            );
          },
        );

        await scenarioStep(page, 'And I click "Apply"', async () => {
          await page.getByTestId('sheet-review-apply').click();
          await expect(page.getByTestId('sheet-review-dialog')).toHaveCount(0);
          await expect(region).toContainText('Header row 2');
        });

        await scenarioStep(page, 'And I click "Import and check"', async () => {
          await page.getByRole('button', { name: 'Import and check' }).click();
        });

        await scenarioStep(page, 'Then I see "Imported 2 tables · 9 rows"', async () => {
          await expect(page.getByTestId('file-import-status')).toContainText(
            'Imported 2 tables · 9 rows',
          );
        });

        await scenarioStep(page, 'When I click "Save datasource"', async () => {
          await page.getByRole('button', { name: 'Save datasource' }).click();
        });

        await scenarioStep(
          page,
          'Then the datasource is listed with the kind "Excel / CSV"',
          async () => {
            await expect(listed).toBeVisible();
            await expect(listed).toContainText('Excel / CSV');
          },
        );

        await scenarioStep(page, 'When I click "Edit" on it', async () => {
          await listed.getByTitle('Edit').click();
        });

        await scenarioStep(
          page,
          'Then I see its two files and the "Region" sheet with header row 2',
          async () => {
            await expect(card('sales_2026.xlsx')).toBeVisible();
            await expect(card('players.csv')).toBeVisible();
            await expect(region).toContainText('Header row 2');
          },
        );
      } finally {
        const { datasources } = await apiJson<{
          datasources: { id: string; name: string }[];
        }>(page, 'GET', '/datasources');
        for (const ds of datasources.filter((d) => d.name === name)) {
          await apiFetch(page, 'DELETE', `/datasources/${ds.id}`);
        }
      }
    },
  );
});
